.wrapper-section-0 {
    width: -webkit-fill-available;
}

.row.section-header {
    display: none;
}

.research-data-table-wrapper {
    margin-top: 0;
}

.btn {
    background: white;
    width: -webkit-fill-available;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 5px;
}
.btn-icon {
    display: flex;
    border: 1.5px solid black;
    font-weight: 600;
    height: 15px;
    width: 15px;
    border-radius: 50%;
    line-height: 20px;
    align-items: center;
    justify-content: center;
    font-size: 10px;
}

.info-card {
    margin: 0;
}
.info-card-header {
    display: flex;
    gap: 20px;
    align-items: center;
    margin: 0 0 10px 0;
}
.info-card-header .Logo {
    width: 130px;
    height: 100px;
}
.info-card-header .Logo img {
    width: inherit;
    height: inherit;
    padding: 10px;
    object-fit: contain;
}

.info-card-header-extra>div:first-child {
    font-size: 18px;
    font-weight: bold;
}
.info-card-header-extra .Name, .info-card-header-extra .Visit {
    line-height: normal;
}

.info-card-row {
    display: flex;
    gap: 20px;
    margin: 0 0 10px 0;
}
.feature .info-card-row {
    display: flex;
    gap: 20px;
    margin: 0 0 40px 0;
}
.info-card-row .row-key {
    display: flex;
    justify-content: flex-end;
    width: 130px;
    text-align: right;
}
.details-wrapper .row-value {
    display: flex;
    flex-direction: row;
    flex-wrap: wrap;
    gap: 5px;
}
.details-wrapper .row-value.Capabilities {
    flex-direction: column;
}
.info-card-row .row-value span {
    background: #eeeeee;
    padding: 2px 5px;
    font-size: 13px;
    white-space: nowrap;
    height: fit-content;
}
.info-card-more {
    display: flex;
    justify-content: flex-end;
}
.info-card-more a {
    text-transform: uppercase;
    font-size: 12px;
    color: #34679a !important;
    font-weight: bold;
    padding: 2px 10px;
    border-radius: 5px;
    text-decoration: none;
}
.info-card-more.hidden{
    display:none;
}
.info-card-more-wrapper {
    /*background: #fff;
    padding: 20px;
    width: calc(100% + 40px);
    margin: 20px 0 0 -20px;*/
    display: flex;
    flex-direction: column;
    gap: 10px;
}
.info-card-more-wrapper.hidden{
    display: none;
}

.details-wrapper {
    display: flex;
    flex-direction: column;
    gap: 10px;
    overflow: hidden;
}
.dataset-page-header {
    background: none;
    border: none;
    margin: 0;
    color: #3b3b3b;
}
.dataset-page-header h3 {
    font-weight: 600;
}
.dataset-page-header .col-md-4.text-right {
    display: none;
}

.list-item {
    display: flex;
    align-items: flex-start;
    gap: 5px;
}
.list-item:before {
    content: '';
    background: black;
    width: 5px;
    height: 5px;
    aspect-ratio: 1;
    border-radius: 50%;
    display: inline-block;
    margin: 6px 0 0;
}

.kp-tab-content .row {
    margin: 0 !important;
}
.kp-tab-content .col-md-12 {
    padding: 0;
}
.multi-section {
    padding: 0 0 20px 0;
    margin: 20px 0 0;
}

.filtering-ui-wrapper.vertical {
    display: flex;
    flex-direction: column;
    padding: 3px 3px 5px 3px;
    background-color: #f6f6f6 !important;
    border:none;
}
.filtering-ui-wrapper>h4.card-title {
    position: relative;
    margin: 5px 0;
}
div.filtering-ui-content div.col {
    width: -webkit-fill-available !important;
}

.filtering-ui-wrapper.vertical .chkbox-combo .form-control {
    width: -webkit-fill-available !important;
    display: flex;
    justify-content: space-between;
    padding: 0 10px;
    font-weight: bold;
    padding: 0;
    background: none;
    border: 0;
}
.filtering-ui-wrapper.vertical .chkbox-combo .form-control span{
    display:none;
}
.filtering-ui-wrapper.vertical .chkbox-combo .options {
    position: relative;
    width: -webkit-fill-available;
    display: flex;
    background: none;
    border: none;
    flex-direction: column;
    gap: 5px;
    max-height: none;
}
.filtering-ui-wrapper.vertical .chkbox-combo .options span {
    border-radius: 5px;
    padding: 0 10px;
    background: white;
}
.filtering-ui-wrapper.vertical .chkbox-combo .options span:hover {
    outline: 0.5px solid #aaaaaa;
}
.filtering-ui-wrapper.vertical .chkbox-combo .options .chkbox {
    display: inline-block;
    margin: 0 5px 0 0;
    appearance: none;
    background: #34679a;
    border-radius: 50%;
    width: 10px;
    height: 10px;
    aspect-ratio: 1;
    position: relative;
}
.filtering-ui-wrapper.vertical .chkbox-combo .options .chkbox:checked:after {
    background: #34679a;
}
.filtering-ui-wrapper.vertical .chkbox-combo .options .chkbox:after {
    content: '';
    background: white;
    width: calc(100% - 5px);
    height: calc(100% - 5px);
    display: block;
    border-radius: 50%;
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
}
.filtering-ui-wrapper.vertical .chkbox-combo .options label {
    width: -webkit-fill-available;
    padding: 0 0 0 3px;
    cursor: pointer;
    border-radius: 5px;
}
.filtering-ui-wrapper.vertical .chkbox-combo .options .chkbox:checked + label {
    
}
.filtering-ui-wrapper.vertical .chkbox-combo .options .chkbox:not(:checked) + label {
   
    opacity: .3;
}

.research-data-table-wrapper {
    display: flex;
    position: relative;
}
.info-page-nav {
    position: absolute;
    top: -40px;
    width: calc(100% + 265px);
    display: flex;
    justify-content: flex-end;
}
.info-page-nav.open {
    justify-content: space-between;
    width: 100%;
}
.info-cards-back {
    width: 100px;
    display: none;
}
.info-page-nav.open .info-cards-back {
    display: block;
}
.info-cards-help {
    display: flex;
    gap: 10px;
    justify-content: flex-end;
}

.vertical-filter{
    /*position: fixed;
    right: 33px;*/
}

.chkbox-combo .options span {
    display: flex;
    align-items: center;
    gap: 5px;
}
.chkbox-combo .options label {
    margin-bottom: 0;
}

.thumbnails-wrapper {
    display: flex;
    flex-direction: column;
    gap: 10px;
    margin: 0 15px 0 0;
    padding-top: 200px;
}
.thumbnails-wrapper.hidden {
    display: none;
}
.thumbnails-wrapper .info-card {
    background: #f6f6f6;
    width: 100px;
    display: flex;
    flex-direction: row;
    cursor: pointer;
    align-items: center;
    justify-content: center;
    padding: 5px 15px;
    gap: 15px;
}
.thumbnails-wrapper .info-card.selected {
    position: absolute;
    top: 0;
    width: 265px;
    height: 190px;
    background: white;
    flex-direction: column;
    gap: 5px;
    padding: 25px 5px;
}
.thumbnails-wrapper .row-value.Logo {
    width: 50px;
    height: 50px;
    display: flex;
    flex-direction: row;
    align-items: baseline;
    justify-content: flex-start;
    opacity: .5
}
.thumbnails-wrapper .info-card.selected .row-value.Logo {
    width: 150px;
    height: 150px;
}
.thumbnails-wrapper .info-card.selected .row-value.Logo, 
.thumbnails-wrapper .info-card:hover .row-value.Logo {
    opacity: 1;
}
.thumbnails-wrapper .row-value.Logo img {
    width: inherit;
    height: inherit;
    object-fit: contain;
    mix-blend-mode: darken;
}
.thumbnails-wrapper .row-value.DCC {
    font-size: 11px;
    display: none;
    width: -webkit-fill-available;
    justify-content: flex-start;
    line-height: normal;
    font-weight: bold;
}

.thumbnails-wrapper .info-card.selected {
    background: white;
    flex-direction: column;
    gap: 5px;
    padding: 25px 5px;
}
.thumbnails-wrapper .info-card.selected .row-value.Logo {
    /*width: 130px;
    height: 50px;*/
}
.thumbnails-wrapper .info-card.selected .row-value.DCC {
    justify-content: center;
}

.imgs_wrapper {
    display: flex;
    flex-direction: row;
    flex-wrap: wrap;
    gap: 10px;
}
.imgs_wrapper img {
    width: calc(33% - 10px);
    height: auto;
    border: 0.5px solid #cccccc;
}

.row-value:has(.mini-card) {
    display: flex;
    flex-direction: row;
    gap: 10px;
    flex-wrap: wrap;
}
.mini-card {
    display: flex;
    flex-direction: column;
    width: calc(50% - 10px);
    background: #eeeeee;
    color: black;
    border: 5px solid #eee;
}
.mini-card-video {
    width: -webkit-fill-available;
    background: white;
}
.mini-card-video video {
    width: -webkit-fill-available;
    display: block;
}
.mini-card-info {
    padding: 5px 10px;
}
.mini-card-title {
    font-weight: bold;
    text-decoration: none;
    color: inherit !important;
}
.mini-card .mini-card-title span {
    background: none;
    font-size: 10px;
    aspect-ratio: 1/1;
    margin: 0 0 0 5px;
    padding: 0;
    display: inline-block;
}
.mini-card-description {
    font-style: italic;
}


.do-color.Epigenomics {
    background: #ffadad50 !important;
}
.do-color.Genomics {
    background: #ffd6a550 !important;
}
.do-color.Glycomics {
    background: #fdffb650 !important;
}
